@inject Services.ThemeService ThemeService
@implements IDisposable

<span class="theme-indicator" style="color: @Theme?.AccentColor;" title="Current theme">
    @ThemeIcon @Theme?.Theme
</span>

@code {
    [CascadingParameter]
    private Services.ThemeInfo? Theme { get; set; }

    private string ThemeIcon => Theme?.Theme switch
    {
        Services.Theme.Dark => "🌙",
        Services.Theme.System => "💻",
        _ => "☀️"
    };

    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        ThemeService.OnChange += _handler;
    }

    public void Dispose()
    {
        ThemeService.OnChange -= _handler;
    }
}

@page "/settings"
@rendermode InteractiveServer
@inject Services.ThemeService ThemeService
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="mb-3">
    <label class="form-label fw-bold">Theme</label>
    <div class="btn-group d-block" role="group">
        @foreach (var t in Enum.GetValues<Services.Theme>())
        {
            <button class="btn @(t == currentTheme ? "btn-primary" : "btn-outline-primary")"
                    @onclick="() => ChangeTheme(t)">
                @t
            </button>
        }
    </div>
</div>

<div class="mb-3">
    <label class="form-label fw-bold" for="accent-color">Accent Color</label>
    <input id="accent-color" type="color" class="form-control form-control-color"
           value="@currentAccent" @onchange="ChangeAccent" />
</div>

<p>
    Current: <strong>@currentTheme</strong> &middot;
    Accent: <span style="color: @currentAccent;">@currentAccent</span>
</p>

@code {
    private Services.Theme currentTheme;
    private string currentAccent = string.Empty;

    [CascadingParameter]
    private Services.ThemeInfo? Theme { get; set; }

    private Action? _handler;

    protected override void OnInitialized()
    {
        currentTheme = ThemeService.Current.Theme;
        currentAccent = ThemeService.Current.AccentColor;
        _handler = () => InvokeAsync(StateHasChanged);
        ThemeService.OnChange += _handler;
    }

    protected override void OnParametersSet()
    {
        if (Theme is not null)
        {
            currentTheme = Theme.Theme;
            currentAccent = Theme.AccentColor;
        }
    }

    private async Task ChangeTheme(Services.Theme theme)
    {
        currentTheme = theme;
        await ThemeService.SetThemeAsync(theme);
    }

    private async Task ChangeAccent(ChangeEventArgs e)
    {
        currentAccent = e.Value?.ToString() ?? currentAccent;
        await ThemeService.SetAccentColorAsync(currentAccent);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= _handler;
    }
}

