using Microsoft.AspNetCore.Components;
using sv_1f28daa94ce94313b1958fd1dd5bed6d.Components;
using sv_1f28daa94ce94313b1958fd1dd5bed6d.Services;

var builder = WebApplication.CreateBuilder(args);

// Add services to the container.
builder.Services.AddRazorComponents()
    .AddInteractiveServerComponents();

// Theme: register CascadingValueSource so the value crosses render-mode boundaries,
// then a scoped ThemeService so each circuit gets independent, mutable state.
builder.Services.AddCascadingValue(sp =>
    new CascadingValueSource<ThemeInfo>(ThemeInfo.Default, isFixed: false));
builder.Services.AddScoped<ThemeService>();

